def solution(a, b):
    """Returns 0 if either input is 0; otherwise returns |a*b| when gcd(a,b)=1, else 1."""
    if a == 0 or b == 0:
        return 0

    x = abs(a)
    y = abs(b)
    while y:
        x, y = y, x % y

    if x == 1:
        return abs(a * b)
    return 1
